package com.ventas.security;
import com.ventas.controller.ProductImageController;import com.ventas.service.*;import com.ventas.repository.ProductImageRepository.Metadata;import com.ventas.security.AuthModels.Identity;import com.ventas.exception.ApiExceptionHandler;
import java.time.OffsetDateTime;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ProductImageController.class) @ActiveProfiles("db") @Import({ApiSecurityConfig.class,SecurityConfig.class,ApiExceptionHandler.class})
class ProductImageApiTest {
 @Autowired MockMvc mvc;@MockBean AuthService auth;@MockBean ProductImageService service;
 void login(String...permissions){when(auth.authenticate(anyString(),anyString())).thenReturn(new Identity(1,"user","N","A","ALM",false,Set.of(permissions),UUID.randomUUID(),OffsetDateTime.now().plusHours(1)));}
 @Test void imagesArePrivateAndWritesRequireManagePermission()throws Exception{mvc.perform(get("/api/productos/7/imagen")).andExpect(status().isUnauthorized());mvc.perform(get("/api/productos/7/imagen/"+"a".repeat(64))).andExpect(status().isUnauthorized());login("PRO.VER");mvc.perform(put("/api/productos/7/imagen").header("Authorization","Bearer test").contentType("application/json").content("{}")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void permittedReadsReturnJpegWithoutPublicCache()throws Exception{login("PRO.VER");when(service.get(7)).thenReturn(new Metadata(7,"a".repeat(64),null));when(service.image(7,"a".repeat(64))).thenReturn(new byte[]{1,2});mvc.perform(get("/api/productos/7/imagen").header("Authorization","Bearer test")).andExpect(status().isOk()).andExpect(jsonPath("$.hash").value("a".repeat(64))).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get("/api/productos/7/imagen/"+"a".repeat(64)).header("Authorization","Bearer test")).andExpect(status().isOk()).andExpect(content().contentType("image/jpeg")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Content-Type-Options","nosniff"));}
 @Test void authorizedWritePassesVersionToService()throws Exception{login("PRO.GESTIONAR");mvc.perform(put("/api/productos/7/imagen").header("Authorization","Bearer test").contentType("application/json").content("{\"imagenBase64\":null,\"quitarImagen\":true,\"version\":null}")).andExpect(status().isOk());verify(service).save(any(),anyString(),eq(7L),argThat(c->c.quitarImagen()&&c.version()==null));}
 @Test void oversizedOrUnknownFieldsCannotReachService()throws Exception{login("PRO.GESTIONAR");for(String body:List.of("{\"imagenBase64\":\""+"A".repeat(2800001)+"\"}","{\"rol\":\"ADM\"}")){mvc.perform(put("/api/productos/7/imagen").header("Authorization","Bearer test").contentType("application/json").content(body)).andExpect(status().isBadRequest());}verifyNoInteractions(service);}
}
